# ==================== Ingebouwde bestanden ====================
INDEX_HTML = '<!DOCTYPE html>\n<html lang="nl">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">\n<meta name="theme-color" content="#0f172a">\n<title>Mijn Spaarpot</title>\n<link rel="manifest" href="/manifest.json">\n<link rel="icon" type="image/png" href="/icon-192.png">\n<link rel="apple-touch-icon" href="/icon-180.png">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<meta name="apple-mobile-web-app-title" content="Spaarpot">\n<style>\n  :root {\n    --c1:#059669; --c2:#10b981; --c3:#34d399;\n    --glow:rgba(16,185,129,.35);\n  }\n  * { margin:0; padding:0; box-sizing:border-box; -webkit-tap-highlight-color:transparent; }\n  html, body { height:100%; }\n  body {\n    font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;\n    background:#0f172a; color:#e2e8f0; display:flex; justify-content:center;\n  }\n  .app {\n    width:100%; max-width:430px; min-height:100vh;\n    background:linear-gradient(180deg,#0f172a 0%,#1e293b 100%);\n    display:flex; flex-direction:column; padding-bottom:96px; position:relative;\n  }\n  .screen { display:none; flex-direction:column; flex:1; }\n  .screen.active { display:flex; }\n\n  /* ===== Gradient headers ===== */\n  .grad {\n    background:linear-gradient(135deg,var(--c1) 0%,var(--c2) 50%,var(--c3) 100%);\n    box-shadow:0 8px 30px var(--glow);\n  }\n\n  /* ===== Login ===== */\n  .login-wrap { flex:1; display:flex; flex-direction:column; justify-content:center; padding:28px 24px; }\n  .login-logo { text-align:center; margin-bottom:26px; }\n  .login-logo .big { font-size:60px; }\n  .login-logo h1 { font-size:26px; font-weight:800; margin-top:8px; }\n  .login-logo p { color:#94a3b8; font-size:14px; margin-top:6px; line-height:1.5; }\n  .tabs { display:flex; background:#1e293b; border-radius:14px; padding:4px; margin-bottom:18px; }\n  .tabs button {\n    flex:1; border:none; background:none; color:#94a3b8; font-size:15px; font-weight:700;\n    padding:11px; border-radius:11px; cursor:pointer;\n  }\n  .tabs button.on { background:var(--c2); color:#fff; }\n  .login-err {\n    display:none; background:rgba(248,113,113,.12); border:1px solid rgba(248,113,113,.35);\n    color:#fca5a5; font-size:13.5px; border-radius:12px; padding:10px 12px; margin-bottom:14px; line-height:1.5;\n  }\n  .login-err.show { display:block; }\n  .skip { text-align:center; margin-top:18px; }\n  .skip button { background:none; border:none; color:#64748b; font-size:14px; cursor:pointer; text-decoration:underline; }\n\n  /* ===== Home (doelenlijst) ===== */\n  .home-header { padding:22px 20px 20px; border-radius:0 0 28px 28px; }\n  .home-header .top { display:flex; justify-content:space-between; align-items:center; }\n  .home-header h1 { font-size:15px; font-weight:600; color:rgba(255,255,255,.85); letter-spacing:.5px; text-transform:uppercase; }\n  .home-header .total { font-size:38px; font-weight:800; color:#fff; letter-spacing:-1px; margin-top:10px; }\n  .home-header .sub { font-size:14px; color:rgba(255,255,255,.85); margin-top:2px; }\n  .btn-icon {\n    background:rgba(255,255,255,.2); border:none; color:#fff;\n    width:38px; height:38px; border-radius:12px; font-size:17px; cursor:pointer;\n  }\n  .goal-list { padding:16px; display:flex; flex-direction:column; gap:12px; }\n  .goal-card {\n    background:#1e293b; border:1px solid #2d3b52; border-radius:20px; padding:16px; cursor:pointer;\n    transition:transform .1s;\n  }\n  .goal-card:active { transform:scale(.98); }\n  .goal-card .row1 { display:flex; align-items:center; gap:12px; }\n  .goal-card .gem {\n    width:48px; height:48px; border-radius:15px; display:flex; align-items:center; justify-content:center;\n    font-size:24px; background:rgba(255,255,255,.06); flex-shrink:0;\n  }\n  .goal-card .gname { font-size:17px; font-weight:800; }\n  .goal-card .gsaved { font-size:13.5px; color:#94a3b8; margin-top:2px; }\n  .goal-card .gpct { margin-left:auto; font-size:15px; font-weight:800; color:var(--c3); }\n  .goal-card .bar { height:9px; background:#0f172a; border-radius:99px; overflow:hidden; margin-top:13px; }\n  .goal-card .fill { height:100%; border-radius:99px; background:linear-gradient(90deg,var(--c2),var(--c3)); transition:width .5s; }\n  .goal-card .done-tag { font-size:12px; font-weight:800; color:var(--c3); margin-top:8px; }\n\n  /* ===== Detail ===== */\n  .header { padding:18px 20px 20px; border-radius:0 0 28px 28px; }\n  .header .top { display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; }\n  .back { background:rgba(255,255,255,.2); border:none; color:#fff; padding:8px 14px; border-radius:12px; font-size:14px; font-weight:700; cursor:pointer; }\n  .goal-name { font-size:24px; font-weight:800; color:#fff; word-break:break-word; }\n  .goal-emoji { font-size:24px; margin-right:6px; }\n  .saved-amount { font-size:38px; font-weight:800; color:#fff; letter-spacing:-1px; margin-top:2px; }\n  .goal-target { font-size:15px; color:rgba(255,255,255,.85); margin-top:2px; }\n  .progress-bar { height:14px; background:rgba(0,0,0,.25); border-radius:99px; overflow:hidden; margin-top:14px; }\n  .progress-fill { height:100%; background:#fff; border-radius:99px; transition:width .6s cubic-bezier(.22,1,.36,1); }\n  .progress-labels { display:flex; justify-content:space-between; margin-top:8px; font-size:13px; color:rgba(255,255,255,.9); font-weight:600; }\n  .celebrate { margin-top:14px; background:rgba(255,255,255,.25); border-radius:14px; padding:10px 14px; text-align:center; font-weight:700; color:#fff; font-size:15px; }\n\n  .stats { display:flex; gap:12px; padding:16px 20px 4px; }\n  .stat { flex:1; background:#1e293b; border:1px solid #334155; border-radius:18px; padding:13px; }\n  .stat .label { font-size:11.5px; color:#94a3b8; font-weight:600; text-transform:uppercase; letter-spacing:.4px; }\n  .stat .value { font-size:18px; font-weight:800; margin-top:4px; }\n  .stat .value.pos { color:var(--c3); }\n  .stat .value.neg { color:#f87171; }\n  .stat .value.blue { color:#60a5fa; }\n\n  .section-title {\n    padding:20px 20px 10px; font-size:14px; font-weight:700; color:#94a3b8;\n    text-transform:uppercase; letter-spacing:.6px; display:flex; justify-content:space-between; align-items:center;\n  }\n  .history { padding:0 16px; display:flex; flex-direction:column; gap:8px; }\n  .tx { display:flex; align-items:center; gap:12px; background:#1e293b; border:1px solid #2d3b52; border-radius:16px; padding:12px 14px; }\n  .tx .icon { width:42px; height:42px; border-radius:13px; display:flex; align-items:center; justify-content:center; font-size:19px; flex-shrink:0; }\n  .tx.save .icon { background:rgba(52,211,153,.15); }\n  .tx.spend .icon { background:rgba(248,113,113,.15); }\n  .tx .info { flex:1; min-width:0; }\n  .tx .desc { font-size:15px; font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n  .tx .date { font-size:12px; color:#94a3b8; margin-top:2px; }\n  .tx .amount { font-size:16px; font-weight:800; white-space:nowrap; }\n  .tx.save .amount { color:var(--c3); }\n  .tx.spend .amount { color:#f87171; }\n  .tx .del { background:none; border:none; color:#475569; font-size:16px; cursor:pointer; padding:6px 2px 6px 8px; }\n  .empty { text-align:center; color:#64748b; padding:40px 30px; font-size:15px; line-height:1.6; }\n  .empty .big { font-size:44px; margin-bottom:10px; }\n\n  /* ===== Onderbalk ===== */\n  .fab-bar {\n    position:fixed; bottom:0; left:50%; transform:translateX(-50%);\n    width:100%; max-width:430px;\n    padding:12px 16px calc(14px + env(safe-area-inset-bottom));\n    background:rgba(15,23,42,.92); backdrop-filter:blur(12px);\n    border-top:1px solid #1e293b; display:none; gap:12px; z-index:30;\n  }\n  .fab-bar.show { display:flex; }\n  .fab {\n    flex:1; border:none; border-radius:18px; padding:16px 10px; font-size:16px; font-weight:800;\n    cursor:pointer; color:#fff; display:flex; align-items:center; justify-content:center; gap:8px; transition:transform .1s;\n  }\n  .fab:active { transform:scale(.96); }\n  .fab.save { background:linear-gradient(135deg,var(--c1),var(--c2)); box-shadow:0 4px 18px var(--glow); }\n  .fab.spend { background:linear-gradient(135deg,#dc2626,#ef4444); box-shadow:0 4px 18px rgba(239,68,68,.35); }\n  .fab.newgoal { background:linear-gradient(135deg,var(--c1),var(--c2)); box-shadow:0 4px 18px var(--glow); }\n\n  /* ===== Sheets ===== */\n  .overlay {\n    position:fixed; inset:0; background:rgba(0,0,0,.6); backdrop-filter:blur(3px);\n    display:none; align-items:flex-end; justify-content:center; z-index:50;\n  }\n  .overlay.open { display:flex; }\n  .sheet {\n    width:100%; max-width:430px; background:#1e293b; border-radius:24px 24px 0 0;\n    padding:22px 20px calc(24px + env(safe-area-inset-bottom));\n    animation:slideUp .25s cubic-bezier(.22,1,.36,1); max-height:88vh; overflow-y:auto;\n  }\n  @keyframes slideUp { from{transform:translateY(60px);opacity:0} to{transform:translateY(0);opacity:1} }\n  .sheet h2 { font-size:20px; font-weight:800; margin-bottom:18px; }\n  .field { margin-bottom:14px; }\n  .field label { display:block; font-size:13px; font-weight:600; color:#94a3b8; margin-bottom:6px; }\n  .field input {\n    width:100%; background:#0f172a; border:1.5px solid #334155; border-radius:14px;\n    padding:14px; font-size:17px; color:#e2e8f0; outline:none;\n  }\n  .field input:focus { border-color:var(--c2); }\n  .quick { display:flex; gap:8px; margin-top:8px; flex-wrap:wrap; }\n  .quick button {\n    background:#0f172a; border:1.5px solid #334155; color:#cbd5e1;\n    border-radius:99px; padding:8px 14px; font-size:14px; font-weight:700; cursor:pointer;\n  }\n  .quick button:active { border-color:var(--c2); color:var(--c3); }\n  .sheet-btns { display:flex; gap:10px; margin-top:20px; }\n  .btn { flex:1; border:none; border-radius:16px; padding:15px; font-size:16px; font-weight:800; cursor:pointer; }\n  .btn.primary { background:var(--c2); color:#fff; }\n  .btn.primary.red { background:#ef4444; }\n  .btn.ghost { background:#334155; color:#cbd5e1; }\n  .btn.danger-line { background:none; color:#f87171; }\n\n  /* ===== Instellingen: thema\'s ===== */\n  .theme-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; }\n  .theme-opt {\n    border:2.5px solid transparent; border-radius:16px; padding:10px 6px; cursor:pointer;\n    background:#0f172a; text-align:center;\n  }\n  .theme-opt.on { border-color:#fff; }\n  .theme-opt .swatch { height:38px; border-radius:11px; margin-bottom:7px; }\n  .theme-opt .tname { font-size:12.5px; font-weight:700; color:#cbd5e1; }\n  .acct-box {\n    background:#0f172a; border:1px solid #334155; border-radius:14px; padding:13px 14px;\n    font-size:14px; color:#cbd5e1; margin-bottom:14px; line-height:1.6; word-break:break-all;\n  }\n  .sync-dot { display:inline-block; width:8px; height:8px; border-radius:99px; margin-right:6px; }\n\n  .toast {\n    position:fixed; bottom:104px; left:50%; transform:translateX(-50%);\n    background:#334155; color:#fff; font-size:14px; font-weight:600;\n    padding:10px 18px; border-radius:99px; z-index:80; display:none; white-space:nowrap;\n    box-shadow:0 6px 20px rgba(0,0,0,.4);\n  }\n  .toast.show { display:block; animation:slideUp .2s; }\n</style>\n</head>\n<body>\n<div class="app" id="appRoot">\n\n  <!-- ========== LOGIN ========== -->\n  <div class="screen" id="scrLogin">\n    <div class="login-wrap">\n      <div class="login-logo">\n        <div class="big">🐷</div>\n        <h1>Mijn Spaarpot</h1>\n        <p>Log in met je e-mail of gsm-nummer,<br>zo ben je je spaargeld nooit kwijt.</p>\n      </div>\n      <div class="tabs">\n        <button id="tabLogin" class="on" onclick="setAuthTab(\'login\')">Inloggen</button>\n        <button id="tabReg" onclick="setAuthTab(\'register\')">Account maken</button>\n      </div>\n      <div class="login-err" id="authErr"></div>\n      <div class="field">\n        <label>E-mail of gsm-nummer</label>\n        <input type="text" id="authId" inputmode="email" autocomplete="username" placeholder="bv. naam@mail.be of 0470 12 34 56">\n      </div>\n      <div class="field">\n        <label>Wachtwoord</label>\n        <input type="password" id="authPw" autocomplete="current-password" placeholder="minstens 4 tekens">\n      </div>\n      <button class="btn primary" style="width:100%" id="authBtn" onclick="doAuth()">Inloggen</button>\n      <div class="skip"><button onclick="skipLogin()">Verder zonder account (alleen op dit toestel)</button></div>\n      <button class="btn ghost" id="installBtnLogin" style="width:100%;margin-top:16px;display:none" onclick="installApp()">📲 App installeren op je telefoon</button>\n    </div>\n  </div>\n\n  <!-- ========== HOME: alle doelen ========== -->\n  <div class="screen" id="scrHome">\n    <div class="home-header grad">\n      <div class="top">\n        <h1>Mijn spaarpotten</h1>\n        <button class="btn-icon" onclick="openSettings()" title="Instellingen">⚙️</button>\n      </div>\n      <div class="total" id="homeTotal">€ 0,00</div>\n      <div class="sub" id="homeSub">totaal gespaard</div>\n    </div>\n    <div class="goal-list" id="goalList"></div>\n  </div>\n\n  <!-- ========== DETAIL: één doel ========== -->\n  <div class="screen" id="scrDetail">\n    <div class="header grad">\n      <div class="top">\n        <button class="back" onclick="showHome()">‹ Terug</button>\n        <button class="btn-icon" onclick="openGoalSheet(true)" title="Doel aanpassen">✏️</button>\n      </div>\n      <div class="goal-name"><span class="goal-emoji" id="dEmoji">🎯</span><span id="dName"></span></div>\n      <div class="saved-amount" id="dSaved">€ 0,00</div>\n      <div class="goal-target" id="dTarget"></div>\n      <div class="progress-bar"><div class="progress-fill" id="dFill" style="width:0%"></div></div>\n      <div class="progress-labels"><span id="dPct">0%</span><span id="dLeft"></span></div>\n      <div class="celebrate" id="dCelebrate" style="display:none">🎉 Proficiat! Je hebt je doel bereikt! 🎉</div>\n    </div>\n    <div class="stats">\n      <div class="stat"><div class="label">Gespaard</div><div class="value pos" id="dIn">€ 0</div></div>\n      <div class="stat"><div class="label">Uitgegeven</div><div class="value neg" id="dOut">€ 0</div></div>\n      <div class="stat"><div class="label">Per week</div><div class="value blue" id="dWeek">—</div></div>\n    </div>\n    <div class="section-title"><span>Geschiedenis</span><span id="dCount" style="font-weight:600;color:#475569;font-size:12px"></span></div>\n    <div class="history" id="dHistory"></div>\n  </div>\n\n  <!-- Onderbalken -->\n  <div class="fab-bar" id="barHome">\n    <button class="fab newgoal" onclick="openGoalSheet(false)">＋ Nieuw spaardoel</button>\n  </div>\n  <div class="fab-bar" id="barDetail">\n    <button class="fab save" onclick="openTxSheet(\'save\')">＋ Sparen</button>\n    <button class="fab spend" onclick="openTxSheet(\'spend\')">－ Uitgave</button>\n  </div>\n</div>\n\n<!-- Sheet: transactie -->\n<div class="overlay" id="txOverlay" onclick="if(event.target===this)closeSheets()">\n  <div class="sheet">\n    <h2 id="txTitle">Geld toevoegen</h2>\n    <div class="field">\n      <label>Bedrag (€)</label>\n      <input type="number" id="txAmount" inputmode="decimal" step="0.01" min="0" placeholder="0,00">\n      <div class="quick">\n        <button onclick="addQuick(5)">+ €5</button>\n        <button onclick="addQuick(10)">+ €10</button>\n        <button onclick="addQuick(20)">+ €20</button>\n        <button onclick="addQuick(50)">+ €50</button>\n      </div>\n    </div>\n    <div class="field">\n      <label>Omschrijving (optioneel)</label>\n      <input type="text" id="txDesc" placeholder="bv. zakgeld, snack, cadeau...">\n    </div>\n    <div class="sheet-btns">\n      <button class="btn ghost" onclick="closeSheets()">Annuleer</button>\n      <button class="btn primary" id="txConfirm" onclick="saveTx()">Toevoegen</button>\n    </div>\n  </div>\n</div>\n\n<!-- Sheet: doel toevoegen/aanpassen -->\n<div class="overlay" id="goalOverlay" onclick="if(event.target===this)closeSheets()">\n  <div class="sheet">\n    <h2 id="goalSheetTitle">Nieuw spaardoel</h2>\n    <div class="field">\n      <label>Waarvoor spaar je?</label>\n      <input type="text" id="goalNameInput" placeholder="bv. Nieuwe fiets, PlayStation, reis...">\n    </div>\n    <div class="field">\n      <label>Emoji</label>\n      <input type="text" id="goalEmojiInput" placeholder="🎯" maxlength="4">\n      <div class="quick">\n        <button onclick="setEmoji(\'🚲\')">🚲</button>\n        <button onclick="setEmoji(\'🎮\')">🎮</button>\n        <button onclick="setEmoji(\'📱\')">📱</button>\n        <button onclick="setEmoji(\'✈️\')">✈️</button>\n        <button onclick="setEmoji(\'👟\')">👟</button>\n        <button onclick="setEmoji(\'🎸\')">🎸</button>\n      </div>\n    </div>\n    <div class="field">\n      <label>Doelbedrag (€)</label>\n      <input type="number" id="goalAmountInput" inputmode="decimal" step="0.01" min="0" placeholder="bv. 500">\n    </div>\n    <div class="sheet-btns">\n      <button class="btn ghost" onclick="closeSheets()">Annuleer</button>\n      <button class="btn primary" onclick="saveGoal()">Opslaan</button>\n    </div>\n    <button class="btn danger-line" id="goalDeleteBtn" style="width:100%;margin-top:8px;display:none" onclick="deleteGoal()">🗑️ Dit spaardoel verwijderen</button>\n  </div>\n</div>\n\n<!-- Sheet: instellingen -->\n<div class="overlay" id="settingsOverlay" onclick="if(event.target===this)closeSheets()">\n  <div class="sheet">\n    <h2>⚙️ Instellingen</h2>\n    <div class="field"><label>Kleur van de app</label>\n      <div class="theme-grid" id="themeGrid"></div>\n    </div>\n    <div class="field" style="margin-top:18px"><label>Account</label>\n      <div class="acct-box" id="acctBox"></div>\n      <button class="btn ghost" id="acctBtn" style="width:100%" onclick="acctAction()">Uitloggen</button>\n    </div>\n    <div class="field" style="margin-top:18px"><label>App op je telefoon</label>\n      <button class="btn primary" id="installBtnSettings" style="width:100%;display:none" onclick="installApp()">📲 App installeren</button>\n      <div class="acct-box" id="installHint" style="margin-top:10px"></div>\n    </div>\n    <div class="sheet-btns">\n      <button class="btn primary" onclick="closeSheets()">Klaar</button>\n    </div>\n  </div>\n</div>\n\n<div class="toast" id="toast"></div>\n\n<script>\n  // ================= Thema\'s =================\n  const THEMES = {\n    groen:  { c1:\'#059669\', c2:\'#10b981\', c3:\'#34d399\', glow:\'rgba(16,185,129,.35)\',  label:\'Groen\' },\n    blauw:  { c1:\'#2563eb\', c2:\'#3b82f6\', c3:\'#60a5fa\', glow:\'rgba(59,130,246,.35)\',  label:\'Blauw\' },\n    paars:  { c1:\'#7c3aed\', c2:\'#8b5cf6\', c3:\'#a78bfa\', glow:\'rgba(139,92,246,.35)\',  label:\'Paars\' },\n    roze:   { c1:\'#db2777\', c2:\'#ec4899\', c3:\'#f472b6\', glow:\'rgba(236,72,153,.35)\',  label:\'Roze\' },\n    oranje: { c1:\'#ea580c\', c2:\'#f97316\', c3:\'#fb923c\', glow:\'rgba(249,115,22,.35)\',  label:\'Oranje\' },\n    goud:   { c1:\'#ca8a04\', c2:\'#eab308\', c3:\'#facc15\', glow:\'rgba(234,179,8,.35)\',   label:\'Goud\' },\n  };\n  function applyTheme(name) {\n    const t = THEMES[name] || THEMES.groen;\n    const r = document.documentElement.style;\n    r.setProperty(\'--c1\',t.c1); r.setProperty(\'--c2\',t.c2); r.setProperty(\'--c3\',t.c3); r.setProperty(\'--glow\',t.glow);\n  }\n\n  // ================= Opslag =================\n  let memStore = {}, storageOk = true;\n  try { localStorage.setItem(\'__t\',\'1\'); localStorage.removeItem(\'__t\'); } catch(e){ storageOk = false; }\n  function lsGet(k){ if(storageOk){const v=localStorage.getItem(k);return v?JSON.parse(v):null;} return memStore[k]??null; }\n  function lsSet(k,v){ if(storageOk) localStorage.setItem(k,JSON.stringify(v)); else memStore[k]=v; }\n  function lsDel(k){ if(storageOk) localStorage.removeItem(k); else delete memStore[k]; }\n\n  // ================= State =================\n  let state = lsGet(\'sp_state\') || migrateOld() || { goals:[], theme:\'groen\' };\n  let session = lsGet(\'sp_session\'); // {token, user} of null\n  let guestMode = lsGet(\'sp_guest\') === true;\n  let currentGoalId = null;\n  let txMode = \'save\';\n  let editingGoal = false;\n  let syncTimer = null, syncStatus = \'idle\'; // idle | saving | ok | fail\n\n  // oude gegevens van vorige versie meenemen\n  function migrateOld() {\n    const g = lsGet(\'sp_goal\'), t = lsGet(\'sp_txs\');\n    if (!g && !t) return null;\n    const goal = g || { name:\'Mijn spaardoel\', emoji:\'🎯\', target:0 };\n    return { goals:[{ id:\'g\'+Date.now(), name:goal.name, emoji:goal.emoji, target:goal.target, txs:t||[] }], theme:\'groen\' };\n  }\n\n  const fmt = n => \'€ \' + n.toLocaleString(\'nl-BE\',{minimumFractionDigits:2,maximumFractionDigits:2});\n  const fmtShort = n => \'€ \' + n.toLocaleString(\'nl-BE\',{maximumFractionDigits:0});\n  const savedOf = g => g.txs.reduce((s,t)=>s+(t.type===\'save\'?t.amount:-t.amount),0);\n  function escapeHtml(s){ return String(s).replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c])); }\n  function toast(msg){ const t=document.getElementById(\'toast\'); t.textContent=msg; t.classList.add(\'show\'); clearTimeout(t._h); t._h=setTimeout(()=>t.classList.remove(\'show\'),2500); }\n\n  // ================= Bewaren + synchroniseren =================\n  function persist() {\n    lsSet(\'sp_state\', state);\n    if (session) {\n      clearTimeout(syncTimer);\n      syncTimer = setTimeout(pushToServer, 800);\n    }\n  }\n  async function pushToServer() {\n    if (!session) return;\n    syncStatus = \'saving\'; renderAcct();\n    try {\n      const r = await fetch(\'/api/data\', {\n        method:\'POST\',\n        headers:{ \'Content-Type\':\'application/json\', \'Authorization\':\'Bearer \'+session.token },\n        body: JSON.stringify(state)\n      });\n      if (r.status === 401) { logout(true); return; }\n      syncStatus = r.ok ? \'ok\' : \'fail\';\n    } catch(e) { syncStatus = \'fail\'; }\n    renderAcct();\n  }\n\n  // ================= Login =================\n  let authTab = \'login\';\n  function setAuthTab(t) {\n    authTab = t;\n    document.getElementById(\'tabLogin\').classList.toggle(\'on\', t===\'login\');\n    document.getElementById(\'tabReg\').classList.toggle(\'on\', t===\'register\');\n    document.getElementById(\'authBtn\').textContent = t===\'login\' ? \'Inloggen\' : \'Account maken\';\n    document.getElementById(\'authErr\').classList.remove(\'show\');\n  }\n  async function doAuth() {\n    const id = document.getElementById(\'authId\').value.trim();\n    const pw = document.getElementById(\'authPw\').value;\n    const err = document.getElementById(\'authErr\');\n    err.classList.remove(\'show\');\n    const btn = document.getElementById(\'authBtn\');\n    btn.disabled = true; btn.textContent = \'Even geduld...\';\n    try {\n      const r = await fetch(\'/api/\'+authTab, {\n        method:\'POST\', headers:{\'Content-Type\':\'application/json\'},\n        body: JSON.stringify({ id, password: pw })\n      });\n      const j = await r.json();\n      if (!r.ok) { err.textContent = j.error || \'Er ging iets mis.\'; err.classList.add(\'show\'); return; }\n      session = { token: j.token, user: j.user };\n      lsSet(\'sp_session\', session); lsDel(\'sp_guest\'); guestMode = false;\n      if (j.data && j.data.goals) {\n        // server heeft al gegevens -> die gebruiken\n        const localHasData = state.goals.some(g => g.txs.length) || state.goals.length > (j.data.goals?.length||0);\n        if (j.data.goals.length || !localHasData) state = j.data;\n        else pushToServer(); // lokaal is rijker -> uploaden\n        lsSet(\'sp_state\', state);\n      } else {\n        pushToServer(); // nieuw account -> lokale gegevens uploaden\n      }\n      applyTheme(state.theme);\n      toast(authTab===\'login\' ? \'Ingelogd ✔\' : \'Account gemaakt ✔\');\n      showHome();\n    } catch(e) {\n      err.textContent = \'Kan de server niet bereiken. Probeer opnieuw.\'; err.classList.add(\'show\');\n    } finally {\n      btn.disabled = false; btn.textContent = authTab===\'login\' ? \'Inloggen\' : \'Account maken\';\n    }\n  }\n  function skipLogin() { guestMode = true; lsSet(\'sp_guest\', true); showHome(); }\n  function logout(expired) {\n    session = null; lsDel(\'sp_session\'); lsDel(\'sp_guest\'); guestMode = false;\n    closeSheets();\n    if (expired) toast(\'Sessie verlopen, log opnieuw in.\');\n    showScreen(\'scrLogin\');\n  }\n\n  // ================= Schermen =================\n  function showScreen(id) {\n    document.querySelectorAll(\'.screen\').forEach(s=>s.classList.remove(\'active\'));\n    document.getElementById(id).classList.add(\'active\');\n    document.getElementById(\'barHome\').classList.toggle(\'show\', id===\'scrHome\');\n    document.getElementById(\'barDetail\').classList.toggle(\'show\', id===\'scrDetail\');\n    window.scrollTo(0,0);\n  }\n  function showHome() { currentGoalId = null; renderHome(); showScreen(\'scrHome\'); }\n  function openGoal(id) { currentGoalId = id; renderDetail(); showScreen(\'scrDetail\'); }\n\n  // ================= Render: home =================\n  function renderHome() {\n    const total = state.goals.reduce((s,g)=>s+savedOf(g),0);\n    document.getElementById(\'homeTotal\').textContent = fmt(total);\n    document.getElementById(\'homeSub\').textContent = state.goals.length\n      ? \'totaal gespaard · \' + state.goals.length + (state.goals.length===1?\' doel\':\' doelen\') : \'totaal gespaard\';\n    const list = document.getElementById(\'goalList\');\n    if (!state.goals.length) {\n      list.innerHTML = \'<div class="empty"><div class="big">🐷</div>Nog geen spaardoelen.<br>Druk op <b>＋ Nieuw spaardoel</b> om te beginnen!</div>\';\n      return;\n    }\n    list.innerHTML = state.goals.map(g => {\n      const saved = savedOf(g);\n      const pct = g.target>0 ? Math.max(0,Math.min(100,saved/g.target*100)) : 0;\n      const done = g.target>0 && saved>=g.target;\n      return `<div class="goal-card" onclick="openGoal(\'${g.id}\')">\n        <div class="row1">\n          <div class="gem">${g.emoji}</div>\n          <div><div class="gname">${escapeHtml(g.name)}</div>\n          <div class="gsaved">${fmt(saved)}${g.target>0?\' van \'+fmt(g.target):\'\'}</div></div>\n          <div class="gpct">${g.target>0?Math.floor(pct)+\'%\':\'\'}</div>\n        </div>\n        <div class="bar"><div class="fill" style="width:${pct}%"></div></div>\n        ${done?\'<div class="done-tag">🎉 Doel bereikt!</div>\':\'\'}\n      </div>`;\n    }).join(\'\');\n  }\n\n  // ================= Render: detail =================\n  function goalById(id){ return state.goals.find(g=>g.id===id); }\n  function renderDetail() {\n    const g = goalById(currentGoalId);\n    if (!g) { showHome(); return; }\n    const totalIn = g.txs.filter(t=>t.type===\'save\').reduce((s,t)=>s+t.amount,0);\n    const totalOut = g.txs.filter(t=>t.type===\'spend\').reduce((s,t)=>s+t.amount,0);\n    const saved = totalIn - totalOut;\n    document.getElementById(\'dEmoji\').textContent = g.emoji;\n    document.getElementById(\'dName\').textContent = g.name;\n    document.getElementById(\'dSaved\').textContent = fmt(saved);\n    document.getElementById(\'dTarget\').textContent = g.target>0 ? \'van \'+fmt(g.target) : \'Stel je doelbedrag in via ✏️\';\n    const pct = g.target>0 ? Math.max(0,Math.min(100,saved/g.target*100)) : 0;\n    document.getElementById(\'dFill\').style.width = pct+\'%\';\n    document.getElementById(\'dPct\').textContent = Math.floor(pct)+\'%\';\n    const left = Math.max(0,g.target-saved);\n    document.getElementById(\'dLeft\').textContent = g.target>0 ? (left>0?\'nog \'+fmt(left)+\' te gaan\':\'Doel bereikt!\') : \'\';\n    document.getElementById(\'dCelebrate\').style.display = (g.target>0 && saved>=g.target)?\'block\':\'none\';\n    document.getElementById(\'dIn\').textContent = fmtShort(totalIn);\n    document.getElementById(\'dOut\').textContent = fmtShort(totalOut);\n    if (g.txs.length>=2) {\n      const dates = g.txs.map(t=>t.date).sort();\n      const weeks = Math.max(1,(new Date(dates[dates.length-1])-new Date(dates[0]))/(7*24*3600*1000));\n      document.getElementById(\'dWeek\').textContent = fmtShort(saved/weeks);\n    } else document.getElementById(\'dWeek\').textContent = \'—\';\n\n    const h = document.getElementById(\'dHistory\');\n    document.getElementById(\'dCount\').textContent = g.txs.length ? g.txs.length+\' items\' : \'\';\n    if (!g.txs.length) {\n      h.innerHTML = \'<div class="empty"><div class="big">💸</div>Nog niets toegevoegd.<br>Druk op <b>＋ Sparen</b> of <b>－ Uitgave</b>.</div>\';\n      return;\n    }\n    h.innerHTML = g.txs.slice().reverse().map(t=>`\n      <div class="tx ${t.type}">\n        <div class="icon">${t.type===\'save\'?\'💰\':\'🛒\'}</div>\n        <div class="info">\n          <div class="desc">${escapeHtml(t.desc||(t.type===\'save\'?\'Gespaard\':\'Uitgave\'))}</div>\n          <div class="date">${new Date(t.date).toLocaleDateString(\'nl-BE\',{day:\'numeric\',month:\'short\',year:\'numeric\'})}</div>\n        </div>\n        <div class="amount">${t.type===\'save\'?\'+\':\'−\'} ${fmt(t.amount)}</div>\n        <button class="del" onclick="delTx(\'${t.id}\')" title="Verwijderen">✕</button>\n      </div>`).join(\'\');\n  }\n\n  // ================= Transacties =================\n  function openTxSheet(mode) {\n    txMode = mode;\n    document.getElementById(\'txTitle\').textContent = mode===\'save\'?\'💰 Geld sparen\':\'🛒 Uitgave toevoegen\';\n    const btn = document.getElementById(\'txConfirm\');\n    btn.textContent = mode===\'save\'?\'Sparen\':\'Uitgave opslaan\';\n    btn.classList.toggle(\'red\', mode===\'spend\');\n    document.getElementById(\'txAmount\').value=\'\'; document.getElementById(\'txDesc\').value=\'\';\n    document.getElementById(\'txOverlay\').classList.add(\'open\');\n    setTimeout(()=>document.getElementById(\'txAmount\').focus(),250);\n  }\n  function addQuick(n){ const i=document.getElementById(\'txAmount\'); i.value=((parseFloat(i.value)||0)+n).toFixed(2).replace(/\\.00$/,\'\'); }\n  function saveTx() {\n    const g = goalById(currentGoalId); if (!g) return;\n    const amount = parseFloat(String(document.getElementById(\'txAmount\').value).replace(\',\',\'.\'));\n    if (!amount || amount<=0) { document.getElementById(\'txAmount\').focus(); return; }\n    g.txs.push({ id:Date.now()+\'\'+Math.random().toString(36).slice(2,6), type:txMode,\n      amount:Math.round(amount*100)/100, desc:document.getElementById(\'txDesc\').value.trim(), date:new Date().toISOString() });\n    persist(); closeSheets(); renderDetail();\n  }\n  function delTx(id) {\n    if (!confirm(\'Dit item verwijderen?\')) return;\n    const g = goalById(currentGoalId); if (!g) return;\n    g.txs = g.txs.filter(t=>t.id!==id);\n    persist(); renderDetail();\n  }\n\n  // ================= Doelen =================\n  function openGoalSheet(edit) {\n    editingGoal = !!edit;\n    document.getElementById(\'goalSheetTitle\').textContent = edit?\'Spaardoel aanpassen\':\'Nieuw spaardoel\';\n    document.getElementById(\'goalDeleteBtn\').style.display = edit?\'block\':\'none\';\n    if (edit) {\n      const g = goalById(currentGoalId); if (!g) return;\n      document.getElementById(\'goalNameInput\').value = g.name;\n      document.getElementById(\'goalEmojiInput\').value = g.emoji;\n      document.getElementById(\'goalAmountInput\').value = g.target||\'\';\n    } else {\n      document.getElementById(\'goalNameInput\').value=\'\';\n      document.getElementById(\'goalEmojiInput\').value=\'\';\n      document.getElementById(\'goalAmountInput\').value=\'\';\n    }\n    document.getElementById(\'goalOverlay\').classList.add(\'open\');\n  }\n  function setEmoji(e){ document.getElementById(\'goalEmojiInput\').value=e; }\n  function saveGoal() {\n    const name = document.getElementById(\'goalNameInput\').value.trim();\n    const emoji = document.getElementById(\'goalEmojiInput\').value.trim() || \'🎯\';\n    const target = parseFloat(String(document.getElementById(\'goalAmountInput\').value).replace(\',\',\'.\'));\n    const tgt = (target && target>0) ? Math.round(target*100)/100 : 0;\n    if (editingGoal) {\n      const g = goalById(currentGoalId); if (!g) return;\n      g.name = name || g.name; g.emoji = emoji; g.target = tgt;\n      persist(); closeSheets(); renderDetail();\n    } else {\n      if (!name) { document.getElementById(\'goalNameInput\').focus(); return; }\n      const g = { id:\'g\'+Date.now()+Math.random().toString(36).slice(2,5), name, emoji, target:tgt, txs:[] };\n      state.goals.push(g);\n      persist(); closeSheets(); openGoal(g.id);\n    }\n  }\n  function deleteGoal() {\n    const g = goalById(currentGoalId); if (!g) return;\n    if (!confirm(\'"\'+g.name+\'" verwijderen? De hele geschiedenis van dit doel gaat verloren.\')) return;\n    state.goals = state.goals.filter(x=>x.id!==currentGoalId);\n    persist(); closeSheets(); showHome();\n  }\n\n  // ================= Instellingen =================\n  function openSettings() {\n    const grid = document.getElementById(\'themeGrid\');\n    grid.innerHTML = Object.entries(THEMES).map(([key,t])=>`\n      <div class="theme-opt ${state.theme===key?\'on\':\'\'}" onclick="pickTheme(\'${key}\')">\n        <div class="swatch" style="background:linear-gradient(135deg,${t.c1},${t.c3})"></div>\n        <div class="tname">${t.label}</div>\n      </div>`).join(\'\');\n    renderAcct();\n    updateInstallUI();\n    document.getElementById(\'settingsOverlay\').classList.add(\'open\');\n  }\n  function pickTheme(key) {\n    state.theme = key; applyTheme(key); persist();\n    document.querySelectorAll(\'.theme-opt\').forEach(el=>el.classList.remove(\'on\'));\n    event.currentTarget.classList.add(\'on\');\n    renderHome(); if (currentGoalId) renderDetail();\n  }\n  function renderAcct() {\n    const box = document.getElementById(\'acctBox\');\n    const btn = document.getElementById(\'acctBtn\');\n    if (!box) return;\n    if (session) {\n      const nice = session.user.replace(/^email:/,\'\').replace(/^tel:/,\'\');\n      const dot = syncStatus===\'fail\' ? \'#f87171\' : syncStatus===\'saving\' ? \'#facc15\' : \'#34d399\';\n      const txt = syncStatus===\'fail\' ? \'synchronisatie mislukt\' : syncStatus===\'saving\' ? \'bezig met opslaan...\' : \'alles bewaard op de server\';\n      box.innerHTML = \'Ingelogd als <b>\'+escapeHtml(nice)+\'</b><br><span class="sync-dot" style="background:\'+dot+\'"></span>\'+txt;\n      btn.textContent = \'Uitloggen\';\n    } else {\n      box.innerHTML = \'⚠️ Je bent <b>niet ingelogd</b>. Je gegevens staan alleen op dit toestel. Maak een account zodat je niets kwijt bent.\';\n      btn.textContent = \'Inloggen / account maken\';\n    }\n  }\n  function acctAction() {\n    if (session) { if (confirm(\'Uitloggen? Je gegevens blijven veilig op de server staan.\')) logout(); }\n    else { closeSheets(); showScreen(\'scrLogin\'); }\n  }\n\n  function closeSheets() {\n    [\'txOverlay\',\'goalOverlay\',\'settingsOverlay\'].forEach(id=>document.getElementById(id).classList.remove(\'open\'));\n  }\n\n  // ================= App installeren (PWA) =================\n  let deferredInstall = null;\n  const isStandalone = window.matchMedia(\'(display-mode: standalone)\').matches || window.navigator.standalone === true;\n  const isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent);\n\n  if (\'serviceWorker\' in navigator) {\n    navigator.serviceWorker.register(\'/sw.js\').catch(()=>{});\n  }\n  window.addEventListener(\'beforeinstallprompt\', e => {\n    e.preventDefault();\n    deferredInstall = e;\n    updateInstallUI();\n  });\n  window.addEventListener(\'appinstalled\', () => {\n    deferredInstall = null;\n    updateInstallUI();\n    toast(\'App geïnstalleerd! 🎉 Kijk tussen je apps.\');\n  });\n  function updateInstallUI() {\n    const btnL = document.getElementById(\'installBtnLogin\');\n    const btnS = document.getElementById(\'installBtnSettings\');\n    const hint = document.getElementById(\'installHint\');\n    const showBtn = !!deferredInstall && !isStandalone;\n    if (btnL) btnL.style.display = showBtn ? \'block\' : \'none\';\n    if (btnS) btnS.style.display = showBtn ? \'block\' : \'none\';\n    if (hint) {\n      if (isStandalone) {\n        hint.innerHTML = \'✅ De app is <b>geïnstalleerd</b> — je gebruikt ze nu als app!\';\n      } else if (showBtn) {\n        hint.innerHTML = \'Druk op de knop hierboven en de app komt tussen je andere apps te staan.\';\n      } else if (isIOS) {\n        hint.innerHTML = \'📲 <b>Installeren op iPhone/iPad:</b><br>1. Open deze pagina in <b>Safari</b><br>2. Druk op de <b>deel-knop</b> (vierkantje met pijl ↑)<br>3. Kies <b>"Zet op beginscherm"</b>\';\n      } else {\n        hint.innerHTML = \'📲 <b>Installeren op Android:</b><br>1. Open deze pagina in <b>Chrome</b><br>2. Druk op het menu <b>⋮</b> rechtsboven<br>3. Kies <b>"App installeren"</b> of <b>"Toevoegen aan startscherm"</b>\';\n      }\n    }\n  }\n  async function installApp() {\n    if (!deferredInstall) return;\n    deferredInstall.prompt();\n    const { outcome } = await deferredInstall.userChoice;\n    if (outcome === \'accepted\') deferredInstall = null;\n    updateInstallUI();\n  }\n\n  // ================= Start =================\n  applyTheme(state.theme);\n  updateInstallUI();\n  async function boot() {\n    if (session) {\n      // gegevens van de server ophalen\n      try {\n        const r = await fetch(\'/api/data\', { headers:{ \'Authorization\':\'Bearer \'+session.token } });\n        if (r.ok) {\n          const j = await r.json();\n          if (j.data && j.data.goals) { state = j.data; lsSet(\'sp_state\', state); applyTheme(state.theme); }\n          syncStatus = \'ok\';\n        } else if (r.status === 401) { logout(true); return; }\n      } catch(e) { syncStatus = \'fail\'; toast(\'Geen verbinding — je werkt nu lokaal.\'); }\n      showHome();\n    } else if (guestMode) {\n      showHome();\n    } else {\n      showScreen(\'scrLogin\');\n    }\n  }\n  boot();\n</script>\n</body>\n</html>\n'

SW_JS = "// Service worker: maakt de app installeerbaar en laat ze offline werken\nconst CACHE = 'spaarpot-v2';\nconst ASSETS = ['/', '/index.html', '/manifest.json', '/icon-192.png', '/icon-512.png', '/icon-180.png'];\n\nself.addEventListener('install', e => {\n  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));\n});\n\nself.addEventListener('activate', e => {\n  e.waitUntil(\n    caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))\n      .then(() => self.clients.claim())\n  );\n});\n\nself.addEventListener('fetch', e => {\n  const url = new URL(e.request.url);\n  // API-verzoeken: altijd naar het netwerk (nooit cachen)\n  if (url.pathname.startsWith('/api/')) return;\n  // App-bestanden: eerst netwerk (altijd nieuwste versie), val terug op cache indien offline\n  e.respondWith(\n    fetch(e.request).then(res => {\n      if (res.ok && e.request.method === 'GET') {\n        const copy = res.clone();\n        caches.open(CACHE).then(c => c.put(e.request, copy));\n      }\n      return res;\n    }).catch(() => caches.match(e.request).then(m => m || caches.match('/index.html')))\n  );\n});\n"

